__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"speakingTopics",{enumerable:!0,get:function(){return o}});const o=[["hometown","Hometown & change","Qu\xea h\u01b0\u01a1ng v\xe0 thay \u0111\u1ed5i","What do you like about the area where you grew up?","Has your hometown changed since you were a child?","Describe a place in your hometown that you would recommend to a visitor.","How can towns preserve their identity while developing?","Should local residents have more influence over urban planning?","My hometown has changed considerably, but the small streets near the river still feel familiar."],["study","Learning something difficult","H\u1ecdc \u0111i\u1ec1u m\u1edbi","What subject do you most enjoy studying?","Do you prefer studying alone or with other people?","Describe something difficult that you successfully learned.","Why do some learners lose confidence when progress is slow?","Should schools assess the learning process as well as final results?","Learning a difficult skill requires patience, regular practice and the willingness to make mistakes."],["work","A job worth doing","C\xf4ng vi\u1ec7c v\xe0 ngh\u1ec1 nghi\u1ec7p","What kind of work would you like to do?","Would you prefer a predictable routine or varied tasks?","Describe a job that you think would be interesting.","How important is salary compared with job satisfaction?","Will technology change the skills employers value most?","A satisfying job can offer both meaningful responsibilities and opportunities for personal development."],["books","A book that stayed with you","S\xe1ch v\xe0 \u0111\u1ecdc hi\u1ec3u","What kinds of books do you read?","Do you read differently on a screen and on paper?","Describe a book that made an impression on you.","Why do some people stop reading for pleasure?","Should public libraries provide more than books?","The book challenged my assumptions and encouraged me to consider a different point of view."],["music","Music in daily life","\xc2m nh\u1ea1c h\u1eb1ng ng\xe0y","When do you usually listen to music?","Has your taste in music changed over time?","Describe a song or piece of music that is special to you.","How can music bring people from different backgrounds together?","Should learning an instrument be part of school education?","Music often reminds us of particular people, places and moments that would otherwise be forgotten."],["technology","A useful device","Thi\u1ebft b\u1ecb v\xe0 c\xf4ng ngh\u1ec7","Which device do you use most often?","Do you find it easy to learn new technology?","Describe a piece of technology that has made your life easier.","When can convenience become dependence?","Who should be responsible for helping people develop digital skills?","A useful device should solve a genuine problem without creating unnecessary distractions."],["travel","A memorable journey","Chuy\u1ebfn \u0111i \u0111\xe1ng nh\u1edb","How do you usually travel around your city?","Do you prefer planning a trip or deciding as you go?","Describe a journey that you remember clearly.","What can travellers learn from unfamiliar places?","How should popular destinations manage the effects of tourism?","The journey was not entirely comfortable, but the unexpected conversations made it memorable."],["food","A meal with a story","B\u1eefa \u0103n v\xe0 v\u0103n h\xf3a","What food do you enjoy preparing?","Do you eat out more often than you used to?","Describe a meal you shared with other people.","Why are traditional recipes important to some families?","How might busy lifestyles affect eating habits?","Sharing a meal gives people an opportunity to slow down, exchange stories and enjoy each other\u2019s company."],["sport","Trying a new sport","Th\u1ec3 thao v\xe0 v\u1eadn \u0111\u1ed9ng","What do you do to stay active?","Do you prefer individual or team activities?","Describe a sport or physical activity you would like to try.","Why do some people enjoy competition while others avoid it?","Should local governments invest more in public sports facilities?","An enjoyable activity is often easier to maintain than an ambitious routine that does not fit daily life."],["nature","A peaceful outdoor place","Thi\xean nhi\xean","How often do you spend time outdoors?","Did you explore natural places as a child?","Describe an outdoor place where you feel relaxed.","What prevents people in cities from accessing nature?","How can natural areas be protected without excluding visitors?","Even a small green space can provide a welcome contrast to the noise and pace of a busy city."],["friendship","A supportive friend","T\xecnh b\u1ea1n","How do you usually keep in touch with friends?","Do you find it easy to make new friends?","Describe a friend who supported you at an important time.","How do friendships change as people get older?","Can online friendships be as meaningful as face-to-face ones?","A supportive friend listens carefully and offers encouragement without pretending to have every answer."],["teacher","Someone who taught you","Ng\u01b0\u1eddi truy\u1ec1n c\u1ea3m h\u1ee9ng","What qualities do you appreciate in a teacher?","Do you enjoy explaining things to other people?","Describe a person who taught you something valuable.","Should teachers focus equally on knowledge and confidence?","How might the role of teachers change in the future?","The best explanation is not always the longest one; it is the one that helps the learner understand."],["film","A film worth discussing","Phim \u1ea3nh","What kinds of films do you enjoy?","Do you prefer watching films at home or in a cinema?","Describe a film that you would like to discuss with a friend.","Can films influence the way people understand social issues?","Why do some audiences prefer familiar stories?","A convincing story can make an unfamiliar situation feel real without telling the audience what to think."],["art","An object of art","Ngh\u1ec7 thu\u1eadt","Do you enjoy visiting galleries?","Did you make things or draw when you were younger?","Describe a work of art or a handmade object that you admire.","Should public art always be easy to understand?","How can communities support artists without limiting their ideas?","A handmade object often reveals the care, decisions and imperfections involved in its creation."],["home","A comfortable home","Nh\xe0 \u1edf","What is your favourite room at home?","Would you prefer living in a city centre or a quieter area?","Describe a home or room you would like to live in.","How do housing needs change across a person\u2019s life?","What makes a neighbourhood suitable for different generations?","A comfortable home depends not only on space and appearance but also on the routines of the people inside it."],["shopping","Buying less but better","Mua s\u1eafm","How do you decide whether to buy something?","Do you prefer shopping online or visiting a shop?","Describe something useful that you bought after careful consideration.","Why do people sometimes buy things they do not need?","Should products be designed to last longer even if they cost more?","Before buying something expensive, I compare alternatives and consider how often I will actually use it."],["environment","Making a small change","M\xf4i tr\u01b0\u1eddng","Do you do anything to reduce waste?","Is it easy to recycle where you live?","Describe a change you made to reduce your environmental impact.","How can individual action and public policy support each other?","Why are some environmentally friendly choices difficult to maintain?","Small changes are easier to sustain when the surrounding systems make them practical and affordable."],["transport","Improving a daily journey","Giao th\xf4ng","What is the busiest part of your daily journey?","Would you cycle more if conditions were different?","Describe a journey you make regularly and how you would improve it.","Should cities give more space to public transport?","How can transport planning consider people who do not own cars?","A reliable journey matters because it affects how people organise their work, education and family responsibilities."],["festival","A celebration to remember","L\u1ec5 h\u1ed9i","What celebrations do you enjoy most?","Do you prefer large gatherings or smaller celebrations?","Describe a celebration that was meaningful to you.","How do celebrations help communities maintain traditions?","Can a traditional festival change without losing its meaning?","The celebration brought together people who rarely had the chance to meet during their ordinary routines."],["skills","A practical skill","K\u1ef9 n\u0103ng th\u1ef1c t\u1ebf","What practical task are you good at?","Do you prefer learning by watching or by trying?","Describe a practical skill that you would like to improve.","Why are practical skills sometimes undervalued in education?","What makes advice from an experienced person useful?","Watching an expert can be helpful, but understanding usually deepens when we attempt the task ourselves."],["news","Keeping informed","Tin t\u1ee9c v\xe0 truy\u1ec1n th\xf4ng","How do you usually hear about current events?","Do you discuss news with other people?","Describe a news story that led you to learn more about a topic.","How can people judge whether a source is trustworthy?","Should speed or accuracy matter more in news reporting?","A responsible reader checks the source, distinguishes evidence from opinion and remains open to correction."],["time","Managing a busy week","Qu\u1ea3n l\xfd th\u1eddi gian","How do you organise your day?","Do you prefer doing difficult tasks early or later?","Describe a time when you managed several responsibilities successfully.","Why do some people feel busy even when they have more convenient technology?","Should workplaces encourage clearer boundaries between work and personal time?","Planning helps me identify priorities, but I also leave room for unexpected tasks and necessary breaks."],["volunteering","Helping a community","Ho\u1ea1t \u0111\u1ed9ng c\u1ed9ng \u0111\u1ed3ng","Have you ever helped with a community activity?","What kinds of help are most needed in your area?","Describe an occasion when you helped someone without expecting payment.","What motivates people to volunteer?","How can organisations support volunteers without relying on them unfairly?","Useful help begins with listening to what people need rather than assuming that we already know."],["language","Communicating across languages","Ng\xf4n ng\u1eef","Why are you learning English?","Which part of language learning do you find most challenging?","Describe a time when you successfully communicated in another language.","What can language learners gain beyond practical communication?","How might translation technology affect the motivation to learn languages?","Communication becomes easier when speakers are willing to rephrase, ask questions and tolerate small mistakes."],["decisions","An important decision","Quy\u1ebft \u0111\u1ecbnh","Do you usually make decisions quickly?","Whose advice do you trust when you are uncertain?","Describe an important decision that you made.","How can people balance careful planning with the need to act?","Should young people be allowed to make more decisions for themselves?","An important decision rarely comes with complete certainty, so it helps to compare the likely consequences."],["success","Progress that mattered","Th\xe0nh t\u1ef1u v\xe0 ti\u1ebfn b\u1ed9","What helps you stay motivated?","Do you celebrate small achievements?","Describe an achievement that required sustained effort.","How should success be measured in education or work?","Can failure contribute to long-term progress?","Progress is not always dramatic; sometimes it is the result of returning to a difficult task many times."],["public-spaces","A place for everyone","Kh\xf4ng gian c\xf4ng c\u1ed9ng","What public places do you use regularly?","Is there a public place you wish your area had?","Describe a public space that people in your community enjoy.","What makes a public space genuinely welcoming?","How should maintenance costs for public facilities be shared?","A welcoming public space allows different people to feel comfortable without requiring them to buy anything."],["photography","A photograph and a memory","\u1ea2nh v\xe0 k\u1ef7 ni\u1ec7m","What do you usually take photographs of?","Do you print photographs or keep them digitally?","Describe a photograph that is important to you.","How has taking photographs changed the way people remember events?","When might putting away a camera improve an experience?","The photograph matters to me because it captures an ordinary moment with people I care about."],["animals","Living alongside animals","\u0110\u1ed9ng v\u1eadt","Did you spend time around animals as a child?","Would you like to have a pet?","Describe an animal you have seen that interested you.","What responsibilities come with keeping a pet?","How can cities make room for wildlife while meeting human needs?","Observing an animal patiently can reveal details that a hurried glance would miss."],["future","A plan for the future","D\u1ef1 \u0111\u1ecbnh t\u01b0\u01a1ng lai","Do you enjoy making long-term plans?","Have your goals changed in the last few years?","Describe something you hope to achieve in the next few years.","How can people prepare for an uncertain future?","Should schools help students explore several possible careers?","A useful plan gives me a direction while leaving enough flexibility to respond to new opportunities."]].map(([o,t,n,s,l,u,h,c,p])=>({id:o,title:t,subtitle:n,part1:[s,l,"Can you give a specific example from your own experience?"],cue:{prompt:u,points:["Explain who or what was involved.","Describe when and where, or in what situation.","Give a concrete detail or example.","Explain why it matters to you and how you feel about it."]},part3:[h,c,"Could someone reasonably disagree with your view? Explain another perspective."],readAloud:p,phrases:["One example that comes to mind is\u2026","The main reason for this is\u2026","On the other hand, it could be argued that\u2026"]}))},250,[]);
